    0.036 * sin(angle * 5.0 - u_time * 0.91 + 1.4) +
    0.021 * sin(angle * 7.0 + u_time * 0.63 - 0.8) +
    0.012 * sin(angle * 11.0 - u_time * 1.72 + sin(angle * 2.0 + u_time * 0.58));
